// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    address owner = address(0xBEEF);

    function setUp() public { 
        c = new RoundFactory();
        vm.prank(owner);
        c.initialize();
    }

    function testFuzz_property(address newRoundImplementation) public {
        vm.prank(owner);

        bool ok;
        try c.updateRoundImplementation(payable(newRoundImplementation)) {
            ok = true;
        } catch {
            ok = false;
        }

        if (newRoundImplementation == address(0)) {
            assertTrue(!ok);
        } else {
            assertTrue(ok && c.roundImplementation() == newRoundImplementation);
        }
    }
}
